from pathlib import Path

BASE = "a5186b4cf2d2a64bbf2f1980f23bb1f11bcf0598"


def replace_exact(path, old, new, expected=1):
    p = Path(path)
    text = p.read_text()
    count = text.count(old)
    if count != expected:
        raise SystemExit(f"{path}: expected {expected} exact matches, found {count}")
    p.write_text(text.replace(old, new))


def replace_method(path, start_marker, end_marker, new_method):
    p = Path(path)
    text = p.read_text()
    if text.count(start_marker) != 1 or text.count(end_marker) != 1:
        raise SystemExit(f"{path}: method markers are not unique")
    start = text.index(start_marker)
    end = text.index(end_marker, start)
    p.write_text(text[:start] + new_method + text[end:])


